import {SoundListener} from './listener.js?v=2';
import{RATE,DURATION,frequency,envelope,synth,resample,analyze,random,spectrum}from'./dsp.js?v=4';
const $=id=>document.getElementById(id),canvas=$('scope'),ctx=canvas.getContext('2d');
const levels=[['First contact','A chirp in the quiet','Follow the dashed curve with a low-to-high hum or whistle. Chirp whenever you like; pause briefly between attempts.',0,55],['Through the static','Find it in the noise','The same chirp, with simulated noise mixed into your recording. Keep your sweep smooth.',1.5,55],['Deep space','Keep your signal clear','More noise, same mission. A sustained rising pitch matters more than volume.',3,52],['Shape matters','Every part tells a story','The χ² consistency check is now active. Keep the sound smooth across the whole sweep.',3,52],['Glitch hunter','Make a signal that belongs','The sine-Gaussian veto is active too. Finish cleanly: avoid clicks, pops, and a sharp squeak.',4,50]];
let unlocked=0;try{unlocked=Math.min(4,Math.max(0,Number(localStorage.getItem('chirplab-progress'))||0))}catch{}
let level=0,base=180,stream,ac,processor,source,mute,capture=false,busy=false,view=null,progress=0,playing=false,listener,monitoring=false,ignoreUntil=0;
function setStatus(s){$('status').textContent=s}
function renderLevels(){ $('levels').replaceChildren(...levels.map((l,i)=>{const b=document.createElement('button');b.className='level'+(i===level?' active':'');b.disabled=i>unlocked||busy;b.setAttribute('aria-label',`Level ${i+1}: ${l[0]}`);b.setAttribute('aria-current',i===level?'step':'false');b.innerHTML=`<span class="num">${i<unlocked?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${l[0]}</strong><small>${['Learn the chirp','Noise +','Noise ++','Add chisquared','Add SG veto'][i]}</small></div>`;b.onclick=()=>selectLevel(i);return b}))}
function selectLevel(i){if(stream)listener=new SoundListener(ac.sampleRate);level=i;view=null;progress=0;const l=levels[i];$('levelTag').textContent=`LEVEL 0${i+1} / ${l[0].toUpperCase()}`;$('levelTitle').textContent=l[1];$('brief').textContent=l[2];$('noiseLabel').textContent='NOISE · '+['LOW','MEDIUM','HIGH','HIGH','VERY HIGH'][i];$('chiBadge').textContent=i>=3?'ACTIVE':'LEVEL 4';$('sgBadge').textContent=i>=4?'ACTIVE':'LEVEL 5';$('match').innerHTML='—<small> / 100</small>';$('chi').textContent='—';$('sg').textContent='—';$('result').hidden=true;renderLevels();draw()}
function draw(){const dpr=devicePixelRatio||1,w=canvas.clientWidth,h=220;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.fillStyle='#101a1e';ctx.fillRect(0,0,w,h);const x=t=>20+t/DURATION*(w-40),y=f=>h-15-Math.log(Math.max(base*.65,f)/(base*.65))/Math.log(8)*(h-30);ctx.strokeStyle='#25373c';ctx.lineWidth=1;for(let i=0;i<7;i++){ctx.beginPath();ctx.moveTo(20+i*(w-40)/6,0);ctx.lineTo(20+i*(w-40)/6,h);ctx.stroke()}for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(0,15+i*(h-30)/4);ctx.lineTo(w,15+i*(h-30)/4);ctx.stroke()}
if(view){for(const fr of view.frames){const max=Math.max(...fr.p,1e-8);for(let k=Math.floor(base*.65*1024/RATE);k<Math.min(fr.p.length,Math.ceil(base*5.2*1024/RATE));k++){const a=Math.max(0,(Math.log10(fr.p[k]/max+1e-7)+3)/3);if(a>.05){ctx.fillStyle=`rgba(91,202,207,${a*.65})`;ctx.fillRect(x(fr.t),y((k+1)*RATE/1024),Math.max(2,(w-40)/140),Math.max(2,y(k*RATE/1024)-y((k+1)*RATE/1024)))}}}ctx.strokeStyle='#79dbdb';ctx.lineWidth=1.7;ctx.beginPath();view.frames.forEach((f,i)=>{if(i===0)ctx.moveTo(x(f.t),y(f.peak));else ctx.lineTo(x(f.t),y(f.peak))});ctx.stroke()}
ctx.strokeStyle='#d6f489';ctx.lineWidth=2;ctx.setLineDash([5,5]);ctx.beginPath();for(let i=0;i<=120;i++){const t=DURATION*i/120;i?ctx.lineTo(x(t),y(frequency(t,base))):ctx.moveTo(x(t),y(frequency(t,base)))}ctx.stroke();ctx.setLineDash([]);ctx.font='9px sans-serif';ctx.fillStyle='#839c9f';ctx.fillText(`${base*4} Hz`,8,14);ctx.fillText(`${base} Hz`,8,h-4);if(capture){ctx.strokeStyle='#eaf7d3';ctx.beginPath();ctx.moveTo(x(progress),0);ctx.lineTo(x(progress),h);ctx.stroke()}}
function lock(on){busy=on;$('record').disabled=on;$('hear').disabled=on;$('demo').disabled=on;$('register').disabled=on;$('reset').disabled=on;$('stop').disabled=on;$('micOff').disabled=on;renderLevels()}
async function context(){ac??=new (window.AudioContext||window.webkitAudioContext)();await ac.resume();return ac}
function listenFrame(input){
 if(!monitoring||playing||performance.now()<ignoreUntil)return;
 const event=listener.push(input);
 if(event.started){view={frames:[]};$('scopeState').textContent='CHIRP DETECTED';setStatus('Following your sound… finish naturally, then pause briefly.');$('result').hidden=true;}
 if(event.active){const samples=listener.join(listener.frames.slice(-Math.ceil(.15*ac.sampleRate/input.length))),p=spectrum(resample(samples,ac.sampleRate));let pk=0;for(let j=Math.floor(base*.7*1024/RATE);j<Math.min(p.length,base*4.6*1024/RATE);j++)if(p[j]>p[pk])pk=j;
 view.frames.push({t:DURATION,at:listener.elapsed,p,peak:pk*RATE/1024});for(const fr of view.frames)fr.t=fr.at/listener.elapsed*DURATION;if(view.frames.length>140)view.frames.shift();$('timer').textContent=`${listener.elapsed.toFixed(1)} s · LISTENING`;draw();}
 if(event.ended){const {audio,background,duration}=event.ended;if(duration<.4){$('scopeState').textContent='LISTENING';setStatus('Short sound detected. Try a smooth rising hum or whistle.');return;}finish(analyze(resample(audio,ac.sampleRate),resample(background,ac.sampleRate),base,levels[level][3]));}
}
async function enable(){
 if(!navigator.mediaDevices?.getUserMedia)throw new Error('Microphone access requires HTTPS or localhost and a supported browser.');
 const audio=await context();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});
 listener=new SoundListener(audio.sampleRate);source=audio.createMediaStreamSource(stream);processor=audio.createScriptProcessor(2048,1,1);mute=audio.createGain();mute.gain.value=0;
 processor.onaudioprocess=e=>listenFrame(e.inputBuffer.getChannelData(0));source.connect(processor);processor.connect(mute);mute.connect(audio.destination);monitoring=true;
 $('record').textContent='Ⅱ   Pause listening';$('micOff').hidden=false;$('scopeState').textContent='LISTENING';setStatus('Listening continuously. Chirp whenever you like, at your own pace. Pause between attempts.');
 stream.getAudioTracks()[0].onended=()=>{if(monitoring){stopMic();setStatus('Microphone disconnected. Reconnect it and start listening again.')}};
}
function finish(result,demo=false){view=result;draw();$('match').innerHTML=`${result.match}<small> / 100</small>`;$('chi').textContent=result.chi.toFixed(2);$('sg').textContent=result.sg>999?'999+':result.sg.toFixed(2);const l=levels[level],passes=result.match>=l[4]&&(level<3||result.chi<3)&&(level<4||result.sg<6);$('result').hidden=false;$('resultTitle').textContent=(demo?'DEMO · ':'')+(passes?(level===4?'You found your signal.':'Signal found!'):'Keep searching.');let feedback=[];if(result.match<l[4])feedback.push(`Aim for ${l[4]}% match: start low and accelerate your pitch near the end.`);if(level>=3&&result.chi>=3)feedback.push('Keep a steady, smooth envelope throughout the chirp (χ² target < 3).');if(level>=4&&result.sg>=6)feedback.push('Excess high-frequency power: finish softly, without a pop or squeak (SG target < 6).');if(result.rms<.001&&!demo)feedback=['The microphone heard very little. Check the input device and move closer.'];$('resultText').textContent=feedback.join(' ')||(demo?'This generated chirp shows the target shape. Try it with your voice to unlock the next level.':'Your rising signal passed this level’s checks. '+(level===4?'All five missions complete. Try again in another register.':'Ready for the next challenge?'));$('next').hidden=!passes||demo||level===4;if(passes&&!demo){unlocked=Math.max(unlocked,Math.min(4,level+1));try{localStorage.setItem('chirplab-progress',unlocked)}catch{}renderLevels()}setStatus(demo?'Generated audio analysed locally. Demo runs do not unlock levels.':monitoring?'Listening for your next attempt. Chirp whenever you like.':'Analysis complete. Audio was processed on your device.');$('scopeState').textContent=monitoring?'LISTENING · READY FOR NEXT CHIRP':'ANALYSIS COMPLETE';$('timer').textContent=demo?'GENERATED DEMO':`${result.duration.toFixed(1)} SECOND ATTEMPT`}
$('record').onclick=async()=>{if(monitoring){stopMic();return;}lock(true);try{await enable()}catch(e){stopMic();setStatus(e.name==='NotAllowedError'?'Microphone permission was denied. Allow it in browser settings, or try the demo.':e.name==='NotFoundError'?'No microphone found. Connect a microphone, or try the demo.':e.message)}finally{lock(false)}};
$('hear').onclick=async()=>{lock(true);try{playing=true;const audio=await context(),data=synth(base),buffer=audio.createBuffer(1,data.length,RATE);buffer.copyToChannel(data,0);const player=audio.createBufferSource(),gain=audio.createGain();gain.gain.value=.5;player.buffer=buffer;player.connect(gain);gain.connect(audio.destination);playing=true;setStatus('Listen for the accelerating rise. Playback ends before recording starts.');player.start();await new Promise(r=>player.onended=r);playing=false;ignoreUntil=performance.now()+500;if(monitoring)listener=new SoundListener(ac.sampleRate);setStatus(monitoring?'Listening again. Chirp whenever you like.':'Your turn: start listening, then hum or whistle the same rising shape.')}catch(e){setStatus('Playback unavailable: '+e.message)}finally{playing=false;lock(false)}};
$('demo').onclick=()=>{lock(true);try{const rng=random(11),bg=Float32Array.from({length:RATE},()=>rng()*.003);finish(analyze(synth(base),bg,base,levels[level][3]),true)}finally{lock(false)}};
$('next').onclick=()=>selectLevel(Math.min(4,level+1));$('register').onchange=()=>{base=Number($('register').value);selectLevel(level)};$('reset').onclick=()=>{unlocked=0;try{localStorage.removeItem('chirplab-progress')}catch{}selectLevel(0);setStatus('Progress reset. Start a new mission.')};
function stopMic(){monitoring=false;listener=null;capture=false;stream?.getTracks().forEach(t=>t.stop());stream=null;$('micOff').hidden=true;processor?.disconnect();source?.disconnect();mute?.disconnect();processor=null;source=null;$('record').textContent='◉   Start listening';$('scopeState').textContent='LISTENING PAUSED';setStatus('Listening paused. Start listening again whenever you’re ready.')}$('stop').onclick=stopMic;$('micOff').onclick=stopMic;window.addEventListener('pagehide',()=>{stopMic();ac?.close()});window.addEventListener('resize',draw);selectLevel(0);
